const wb = $input.first().json;
const body = wb.body ?? wb;

const source     = body.source     ?? 'email';
const from       = body.from       ?? '';
const subject    = body.subject    ?? '';
const content    = body.body       ?? body.content ?? '';
const source_ref = body.source_ref ?? '';

const systemPrompt = `Eres un agente de procesamiento de pedidos para OrderFlow.
Tu trabajo es analizar pedidos que llegan por email u otros canales,
extraer la información relevante, y usar las herramientas disponibles para procesarlos.

PROCESO:
1. Analiza el contenido del pedido (asunto + cuerpo del mensaje)
2. Identifica el proveedor mencionado. Usa search_suppliers para buscarlo.
3. Si encuentras el proveedor, usa get_supplier_products para ver sus productos disponibles.
4. Comprueba duplicados con check_duplicate_order.
5. Si no es duplicado, usa create_order para crear el pedido con los items detectados.
6. Responde SOLO con un JSON con esta estructura exacta:
   { "status": "success", "order_id": 123, "supplier": "Nombre", "items_count": 3, "confidence": 0.95, "message": "Pedido creado" }

Si no puedes identificar el proveedor: status "error".
Si es duplicado: status "duplicate" y order_id del pedido existente.`;

const userMessage = `Procesa este pedido:
Origen: ${source}
De: ${from}
Asunto: ${subject}
Referencia: ${source_ref}

Contenido:
${content}`;

const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user',   content: userMessage  },
];

const tools = [
  {
    type: 'function',
    function: {
      name: 'search_suppliers',
      description: 'Busca proveedores por nombre o categoría',
      parameters: {
        type: 'object',
        properties: {
          query:       { type: 'string',  description: 'Texto a buscar en nombre' },
          category:    { type: 'string',  description: 'Categoría (frutas, carne, bebidas...)' },
          active_only: { type: 'boolean', description: 'Solo activos', default: true },
        },
      },
    },
  },
  {
    type: 'function',
    function: {
      name: 'get_supplier_products',
      description: 'Lista productos de un proveedor',
      parameters: {
        type: 'object',
        properties: {
          supplier_id: { type: 'number', description: 'ID del proveedor' },
          active_only: { type: 'boolean', description: 'Solo activos', default: true },
        },
        required: ['supplier_id'],
      },
    },
  },
  {
    type: 'function',
    function: {
      name: 'create_order',
      description: 'Crea un nuevo pedido con sus líneas',
      parameters: {
        type: 'object',
        properties: {
          supplier_id: { type: 'number', description: 'ID del proveedor' },
          source:      { type: 'string', description: 'Origen: email, web, manual' },
          raw_content: { type: 'string', description: 'Texto original del pedido' },
          source_ref:  { type: 'string', description: 'Referencia externa' },
          items: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                product_name: { type: 'string' },
                quantity:     { type: 'number' },
                unit:         { type: 'string' },
              },
              required: ['product_name', 'quantity', 'unit'],
            },
          },
        },
        required: ['supplier_id', 'source', 'raw_content', 'items'],
      },
    },
  },
  {
    type: 'function',
    function: {
      name: 'check_duplicate_order',
      description: 'Comprueba si existe un pedido similar reciente',
      parameters: {
        type: 'object',
        properties: {
          supplier_id:  { type: 'number', description: 'ID del proveedor' },
          source_ref:   { type: 'string', description: 'Referencia externa' },
          hours_window: { type: 'number', description: 'Ventana en horas', default: 24 },
        },
        required: ['supplier_id'],
      },
    },
  },
  {
    type: 'function',
    function: {
      name: 'update_order_status',
      description: 'Actualiza el estado de un pedido',
      parameters: {
        type: 'object',
        properties: {
          order_id: { type: 'number', description: 'ID del pedido' },
          status:   { type: 'string', enum: ['pending','validated','confirmed','sent','delivered','cancelled','error'] },
          notes:    { type: 'string', description: 'Notas opcionales' },
        },
        required: ['order_id', 'status'],
      },
    },
  },
  {
    type: 'function',
    function: {
      name: 'get_order_summary',
      description: 'Resumen de pedidos recientes',
      parameters: {
        type: 'object',
        properties: {
          days:   { type: 'number', description: 'Días hacia atrás', default: 7 },
          status: { type: 'string', enum: ['pending','validated','confirmed','sent','delivered','cancelled','error'] },
        },
      },
    },
  },
];

const deepseek_request = {
  model: 'deepseek-chat',
  messages,
  tools,
  tool_choice: 'auto',
  temperature: 0.1,
};

return [{ json: { messages, tools, source, source_ref, raw_content: content, deepseek_request } }];

// Respuesta inicial de DeepSeek
const firstResponse = $input.first().json;

// Contexto del nodo anterior (mensajes, tools, source info)
const context = $('Preparar contexto').first().json;

// API key de DeepSeek — configura DEEPSEEK_API_KEY en n8n:
// Settings > Variables > New Variable > DEEPSEEK_API_KEY
const DEEPSEEK_API_KEY = $env.DEEPSEEK_API_KEY ?? '';
const MCP_URL = 'http://127.0.0.1:3200/tools';
const MAX_ITER = 8;

let messages = [...context.messages];
const tools  = context.tools;

const firstChoice = firstResponse.choices?.[0];
if (!firstChoice) {
  return [{ json: { status: 'error', order_id: null, supplier: null, items_count: 0, confidence: 0, message: 'Sin respuesta de DeepSeek' } }];
}
messages.push(firstChoice.message);

let finalContent = null;

for (let iter = 0; iter < MAX_ITER; iter++) {
  const lastMsg = messages[messages.length - 1];

  // Sin tool_calls → respuesta final
  if (!lastMsg.tool_calls || lastMsg.tool_calls.length === 0) {
    finalContent = lastMsg.content;
    break;
  }

  // Ejecutar cada tool call contra el HTTP Bridge
  for (const tc of lastMsg.tool_calls) {
    let args;
    try { args = JSON.parse(tc.function.arguments); } catch { args = {}; }

    let toolResult;
    try {
      const r = await fetch(`${MCP_URL}/${tc.function.name}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(args),
      });
      toolResult = await r.json();
    } catch (e) {
      toolResult = { error: `Tool call falló: ${e.message}` };
    }

    messages.push({
      role: 'tool',
      tool_call_id: tc.id,
      content: JSON.stringify(toolResult),
    });
  }

  // Nueva llamada a DeepSeek con el historial completo
  try {
    const r = await fetch('https://api.deepseek.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${DEEPSEEK_API_KEY}`,
      },
      body: JSON.stringify({ model: 'deepseek-chat', messages, tools, tool_choice: 'auto', temperature: 0.1 }),
    });
    if (!r.ok) {
      const txt = await r.text();
      return [{ json: { status: 'error', order_id: null, supplier: null, items_count: 0, confidence: 0, message: `DeepSeek error ${r.status}: ${txt}` } }];
    }
    const data = await r.json();
    const choice = data.choices?.[0];
    if (!choice) break;
    messages.push(choice.message);
  } catch (e) {
    return [{ json: { status: 'error', order_id: null, supplier: null, items_count: 0, confidence: 0, message: `DeepSeek request falló: ${e.message}` } }];
  }
}

// Si se agotaron las iteraciones sin respuesta final
if (finalContent === null) {
  const last = messages[messages.length - 1];
  finalContent = last?.content ?? '';
}

// Parsear JSON de la respuesta final
let result;
try {
  const match = finalContent.match(/\{[\s\S]*\}/);
  result = match ? JSON.parse(match[0]) : { status: 'error', order_id: null, supplier: null, items_count: 0, confidence: 0, message: finalContent };
} catch {
  result = { status: 'error', order_id: null, supplier: null, items_count: 0, confidence: 0, message: finalContent };
}

return [{ json: result }];
